class Workspace extends StatefulWidget {
  const Workspace({super.key});
  @override State<Workspace> createState() => _WorkspaceState();
}

class _WorkspaceState extends State<Workspace> {
  final db = AppDatabase();
  int index = 0;
  static const modules = <ModuleInfo>[
    ModuleInfo('Dashboard', Icons.dashboard_outlined), ModuleInfo('Baustellen', Icons.location_on_outlined), ModuleInfo('Kunden', Icons.people_outline), ModuleInfo('Aufträge', Icons.assignment_outlined), ModuleInfo('Mitarbeiter', Icons.groups_outlined), ModuleInfo('Zeiterfassung', Icons.schedule_outlined), ModuleInfo('Kalender', Icons.calendar_month_outlined), ModuleInfo('Berichte', Icons.description_outlined), ModuleInfo('Material', Icons.inventory_2_outlined), ModuleInfo('Maschinen', Icons.construction_outlined), ModuleInfo('Aufgaben', Icons.checklist_outlined),
  ];
  @override void dispose() { db.close(); super.dispose(); }
  @override Widget build(BuildContext context) {
    final mobile = MediaQuery.sizeOf(context).width < 800;
    return Scaffold(
      appBar: AppBar(backgroundColor: green, foregroundColor: Colors.white, title: Row(children: [const Icon(Icons.park_outlined), const SizedBox(width: 10), Text(modules[index].label, style: const TextStyle(fontWeight: FontWeight.w700))]), actions: [IconButton(onPressed: () {}, icon: const Icon(Icons.notifications_none)), const SizedBox(width: 8)]),
      body: Row(children: [if (!mobile) Sidebar(index: index, onTap: (i) => setState(() => index = i)), Expanded(child: _page())]),
      bottomNavigationBar: mobile ? NavigationBar(selectedIndex: index < 5 ? index : 0, onDestinationSelected: (i) => setState(() => index = i), destinations: const [NavigationDestination(icon: Icon(Icons.dashboard_outlined), label: 'Start'), NavigationDestination(icon: Icon(Icons.location_on_outlined), label: 'Baustellen'), NavigationDestination(icon: Icon(Icons.people_outline), label: 'Kunden'), NavigationDestination(icon: Icon(Icons.schedule_outlined), label: 'Zeit'), NavigationDestination(icon: Icon(Icons.more_horiz), label: 'Mehr')]) : null,
    );
  }
  Widget _page() {
    if (index == 0) return Dashboard(db: db, open: (i) => setState(() => index = i));
    if (index == 6) return const CalendarPage();
    return ModulePage(db: db, kind: moduleKinds[index]);
  }
}

class ModuleInfo { final String label; final IconData icon; const ModuleInfo(this.label, this.icon); }
class Sidebar extends StatelessWidget {
  final int index; final ValueChanged<int> onTap;
  const Sidebar({super.key, required this.index, required this.onTap});
  @override Widget build(BuildContext context) => Container(width: 112, color: Colors.white, child: Column(children: [Padding(padding: const EdgeInsets.all(9), child: Image.asset('assets/images/logo.png', height: 55)), Expanded(child: ListView.builder(itemCount: Workspace.modules.length, itemBuilder: (_, i) { final m = Workspace.modules[i]; final selected = i == index; return Padding(padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2), child: InkWell(borderRadius: BorderRadius.circular(14), onTap: () => onTap(i), child: Container(padding: const EdgeInsets.symmetric(vertical: 8), decoration: BoxDecoration(color: selected ? paleGreen : Colors.transparent, borderRadius: BorderRadius.circular(14)), child: Column(children: [Icon(m.icon, color: selected ? green : Colors.black54, size: 27), const SizedBox(height: 3), Text(m.label, textAlign: TextAlign.center, style: TextStyle(fontSize: 12, fontWeight: selected ? FontWeight.w700 : FontWeight.w500, color: selected ? darkGreen : Colors.black87))]))); })))]));
}

class Dashboard extends StatefulWidget { final AppDatabase db; final ValueChanged<int> open; const Dashboard({super.key, required this.db, required this.open}); @override State<Dashboard> createState() => _DashboardState(); }
class _DashboardState extends State<Dashboard> {
