enum ModuleKind { sites, customers, orders, employees, time, reports, materials, machines, tasks }
const moduleKinds = [ModuleKind.sites,ModuleKind.customers,ModuleKind.orders,ModuleKind.employees,ModuleKind.time,ModuleKind.sites,ModuleKind.reports,ModuleKind.materials,ModuleKind.machines,ModuleKind.tasks];
String moduleTitle(ModuleKind k)=>switch(k){ModuleKind.sites=>'Baustellen',ModuleKind.customers=>'Kunden',ModuleKind.orders=>'Aufträge',ModuleKind.employees=>'Mitarbeiter',ModuleKind.time=>'Zeiterfassung',ModuleKind.reports=>'Berichte',ModuleKind.materials=>'Material',ModuleKind.machines=>'Maschinen',ModuleKind.tasks=>'Aufgaben'};
IconData moduleIcon(ModuleKind k)=>switch(k){ModuleKind.sites=>Icons.location_on,ModuleKind.customers=>Icons.people,ModuleKind.orders=>Icons.assignment,ModuleKind.employees=>Icons.groups,ModuleKind.time=>Icons.schedule,ModuleKind.reports=>Icons.description,ModuleKind.materials=>Icons.inventory_2,ModuleKind.machines=>Icons.construction,ModuleKind.tasks=>Icons.checklist};

class ModulePage extends StatefulWidget { final AppDatabase db; final ModuleKind kind; const ModulePage({super.key,required this.db,required this.kind}); @override State<ModulePage> createState()=>_ModulePageState(); }
class _ModulePageState extends State<ModulePage> {
  late Future<List<dynamic>> future; String search='';
  @override void initState(){super.initState();load();}
  void load()=>future=_query();
  Future<List<dynamic>> _query() async { switch(widget.kind){case ModuleKind.sites:return widget.db.select(widget.db.sites).get();case ModuleKind.customers:return widget.db.select(widget.db.customers).get();case ModuleKind.orders:return widget.db.select(widget.db.orders).get();case ModuleKind.employees:return widget.db.select(widget.db.employees).get();case ModuleKind.time:return widget.db.select(widget.db.timeEntries).get();case ModuleKind.reports:return widget.db.select(widget.db.reports).get();case ModuleKind.materials:return widget.db.select(widget.db.materialsTable).get();case ModuleKind.machines:return widget.db.select(widget.db.machinesTable).get();case ModuleKind.tasks:return widget.db.select(widget.db.tasksTable).get();} }
  String primary(dynamic x)=>switch(widget.kind){ModuleKind.sites=>x.title,ModuleKind.customers=>x.name,ModuleKind.orders=>x.title,ModuleKind.employees=>x.name,ModuleKind.time=>x.employeeName,ModuleKind.reports=>x.title,ModuleKind.materials=>x.name,ModuleKind.machines=>x.name,ModuleKind.tasks=>x.title};
  String secondary(dynamic x)=>switch(widget.kind){ModuleKind.sites=>x.address,ModuleKind.customers=>[x.contact,x.phone,x.address].where((v)=>v.toString().isNotEmpty).join(' • '),ModuleKind.orders=>'${x.status} • ${x.date} • ${x.price.toStringAsFixed(2)} €',ModuleKind.employees=>'${x.role} • ${x.targetHours.toStringAsFixed(1)} h/Woche',ModuleKind.time=>'${x.date.day.toString().padLeft(2,'0')}.${x.date.month.toString().padLeft(2,'0')}.${x.date.year} • ${x.startTime.hour.toString().padLeft(2,'0')}:${x.startTime.minute.toString().padLeft(2,'0')}',ModuleKind.reports=>'${x.date} • ${x.content}',ModuleKind.materials=>'${x.stock} ${x.unit} • ${x.category ?? ''}',ModuleKind.machines=>'${x.status} • ${x.operatingHours} h',ModuleKind.tasks=>'${x.status} • ${x.priority} • ${x.category}'};
  @override Widget build(BuildContext context)=>Stack(children:[const Watermark(),FutureBuilder<List<dynamic>>(future:future,builder:(_,s){if(s.connectionState==ConnectionState.waiting)return const Center(child:CircularProgressIndicator(color:green));if(s.hasError)return Center(child:Text('Fehler: ${s.error}'));final items=(s.data??[]).where((x)=>('${primary(x)} ${secondary(x)}').toLowerCase().contains(search.toLowerCase())).toList();return ListView(padding:const EdgeInsets.fromLTRB(30,26,30,40),children:[Row(children:[Container(width:52,height:52,decoration:BoxDecoration(color:paleGreen,borderRadius:BorderRadius.circular(14)),child:Icon(moduleIcon(widget.kind),color:green)),const SizedBox(width:14),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(moduleTitle(widget.kind),style:const TextStyle(fontSize:29,fontWeight:FontWeight.w700,color:darkGreen)),Text('Einträge verwalten, suchen und bearbeiten',style:const TextStyle(color:Colors.black54))])),FilledButton.icon(style:FilledButton.styleFrom(backgroundColor:green),onPressed:()=>edit(),icon:const Icon(Icons.add),label:const Text('Neu'))]),const SizedBox(height:18),TextField(onChanged:(v)=>setState(()=>search=v),decoration:InputDecoration(prefixIcon:const Icon(Icons.search),hintText:'${moduleTitle(widget.kind)} durchsuchen …',filled:true,fillColor:Colors.white,border:OutlineInputBorder(borderRadius:BorderRadius.circular(14),borderSide:BorderSide.none))),const SizedBox(height:12),Text('${items.length} ${moduleTitle(widget.kind)}',style:const TextStyle(fontWeight:FontWeight.w700,color:darkGreen)),const SizedBox(height:8),if(items.isEmpty)Card(child:Padding(padding:const EdgeInsets.all(35),child:Column(children:[Icon(moduleIcon(widget.kind),size:50,color:Colors.black26),const SizedBox(height:10),Text(search.isEmpty?'Noch keine Einträge vorhanden.':'Keine passenden Einträge gefunden.'),const SizedBox(height:12),if(search.isEmpty)OutlinedButton.icon(onPressed:()=>edit(),icon:const Icon(Icons.add),label:const Text('Eintrag anlegen'))]))) else ...items.map((x)=>Card(margin:const EdgeInsets.only(bottom:9),child:ListTile(contentPadding:const EdgeInsets.symmetric(horizontal:18,vertical:5),leading:CircleAvatar(backgroundColor:paleGreen,child:Icon(moduleIcon(widget.kind),color:green)),title:Text(primary(x),style:const TextStyle(fontWeight:FontWeight.w700)),subtitle:Text(secondary(x),maxLines:2,overflow:TextOverflow.ellipsis),trailing:Wrap(children:[IconButton(tooltip:'Bearbeiten',onPressed:()=>edit(x),icon:const Icon(Icons.edit_outlined)),IconButton(tooltip:'Löschen',onPressed:()=>remove(x),icon:const Icon(Icons.delete_outline))]),onTap:()=>edit(x))))]);})]);
  Future<void> edit([dynamic item]) async { final values=await showDialog<Map<String,String>>(context:context,builder:(_)=>EntryDialog(db:widget.db,kind:widget.kind,item:item)); if(values==null)return; try{if(item==null)await insert(values);else await update(item,values);setState(load);if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Gespeichert.'),backgroundColor:green));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Speichern fehlgeschlagen: $e'),backgroundColor:Colors.red));} }
