  Future<void> insert(Map<String,String> v) async { switch(widget.kind){case ModuleKind.sites:await widget.db.into(widget.db.sites).insert(SitesCompanion.insert(title:v['title']!,address:v['address']!,customerId:_nullableText(v['customerId']));case ModuleKind.customers:await widget.db.into(widget.db.customers).insert(CustomersCompanion.insert(id:_id(),name:v['name']!,contact:Value(v['contact']??''),phone:Value(v['phone']??''),address:Value(v['address']??'')));case ModuleKind.orders:await widget.db.into(widget.db.orders).insert(OrdersCompanion.insert(id:_id(),title:v['title']!,customerId:_nullableText(v['customerId']),siteId:_nullableInt(v['siteId']),status:Value(v['status']??'Neu'),date:v['date']!,price:Value(_num(v['price']))));case ModuleKind.employees:await widget.db.into(widget.db.employees).insert(EmployeesCompanion.insert(id:_id(),name:v['name']!,role:v['role']!,targetHours:Value(_num(v['targetHours']))));case ModuleKind.time:await widget.db.into(widget.db.timeEntries).insert(TimeEntriesCompanion.insert(siteId:int.parse(v['siteId']!),employeeName:v['employeeName']!,date:_date(v['date']!),startTime:_dt(v['date']!,v['startTime']!),endTime:Value((v['endTime']??'').isEmpty?null:_dt(v['date']!,v['endTime']!)),breakMinutes:Value(_num(v['breakMinutes'])),notes:Value(_nullableString(v['notes']))));case ModuleKind.reports:await widget.db.into(widget.db.reports).insert(ReportsCompanion.insert(id:_id(),siteId:_nullableInt(v['siteId']),title:v['title']!,date:v['date']!,content:v['content']??''));case ModuleKind.materials:await widget.db.into(widget.db.materialsTable).insert(MaterialsTableCompanion.insert(name:v['name']!,articleNumber:Value(_nullableString(v['articleNumber'])),category:Value(_nullableString(v['category'])),unit:Value(v['unit']??'Stk'),stock:Value(_num(v['stock'])),minimumStock:Value(_num(v['minimumStock'])),location:Value(_nullableString(v['location'])),unitPrice:Value(_nullableDouble(v['unitPrice'])),notes:Value(_nullableString(v['notes']))));case ModuleKind.machines:await widget.db.into(widget.db.machinesTable).insert(MachinesTableCompanion.insert(name:v['name']!,serialNumber:Value(_nullableString(v['serialNumber'])),operatingHours:Value(_num(v['operatingHours'])),status:Value(v['status']??'bereit'),notes:Value(_nullableString(v['notes']))));case ModuleKind.tasks:await widget.db.into(widget.db.tasksTable).insert(TasksTableCompanion.insert(title:v['title']!,description:Value(_nullableString(v['description'])),siteId:_nullableInt(v['siteId']),category:v['category']!,priority:Value(v['priority']??'normal'),status:Value(v['status']??'offen'),dueDate:Value((v['dueDate']??'').isEmpty?null:_date(v['dueDate']!)));} }
  Future<void> update(dynamic x,Map<String,String> v) async { switch(widget.kind){case ModuleKind.sites:await(widget.db.update(widget.db.sites)..where((t)=>t.id.equals(x.id))).write(SitesCompanion(title:Value(v['title']!),address:Value(v['address']!),customerId:_nullableText(v['customerId'])));case ModuleKind.customers:await(widget.db.update(widget.db.customers)..where((t)=>t.id.equals(x.id))).write(CustomersCompanion(name:Value(v['name']!),contact:Value(v['contact']??''),phone:Value(v['phone']??''),address:Value(v['address']??'')));case ModuleKind.orders:await(widget.db.update(widget.db.orders)..where((t)=>t.id.equals(x.id))).write(OrdersCompanion(title:Value(v['title']!),customerId:_nullableText(v['customerId']),siteId:_nullableInt(v['siteId']),status:Value(v['status']??'Neu'),date:Value(v['date']!),price:Value(_num(v['price']))));case ModuleKind.employees:await(widget.db.update(widget.db.employees)..where((t)=>t.id.equals(x.id))).write(EmployeesCompanion(name:Value(v['name']!),role:Value(v['role']!),targetHours:Value(_num(v['targetHours']))));case ModuleKind.time:await(widget.db.update(widget.db.timeEntries)..where((t)=>t.id.equals(x.id))).write(TimeEntriesCompanion(siteId:Value(int.parse(v['siteId']!)),employeeName:Value(v['employeeName']!),date:Value(_date(v['date']!)),startTime:Value(_dt(v['date']!,v['startTime']!)),endTime:Value((v['endTime']??'').isEmpty?null:_dt(v['date']!,v['endTime']!)),breakMinutes:Value(_num(v['breakMinutes'])),notes:Value(_nullableString(v['notes']))));case ModuleKind.reports:await(widget.db.update(widget.db.reports)..where((t)=>t.id.equals(x.id))).write(ReportsCompanion(title:Value(v['title']!),siteId:_nullableInt(v['siteId']),date:Value(v['date']!),content:Value(v['content']??'')));case ModuleKind.materials:await(widget.db.update(widget.db.materialsTable)..where((t)=>t.id.equals(x.id))).write(MaterialsTableCompanion(name:Value(v['name']!),articleNumber:Value(_nullableString(v['articleNumber'])),category:Value(_nullableString(v['category'])),unit:Value(v['unit']??'Stk'),stock:Value(_num(v['stock'])),minimumStock:Value(_num(v['minimumStock'])),location:Value(_nullableString(v['location'])),unitPrice:Value(_nullableDouble(v['unitPrice'])),notes:Value(_nullableString(v['notes'])),updatedAt:Value(DateTime.now())));case ModuleKind.machines:await(widget.db.update(widget.db.machinesTable)..where((t)=>t.id.equals(x.id))).write(MachinesTableCompanion(name:Value(v['name']!),serialNumber:Value(_nullableString(v['serialNumber'])),operatingHours:Value(_num(v['operatingHours'])),status:Value(v['status']??'bereit'),notes:Value(_nullableString(v['notes']))));case ModuleKind.tasks:await(widget.db.update(widget.db.tasksTable)..where((t)=>t.id.equals(x.id))).write(TasksTableCompanion(title:Value(v['title']!),description:Value(_nullableString(v['description'])),siteId:_nullableInt(v['siteId']),category:Value(v['category']!),priority:Value(v['priority']??'normal'),status:Value(v['status']??'offen'),dueDate:Value((v['dueDate']??'').isEmpty?null:_date(v['dueDate']!)));} }
