class EntryDialog extends StatefulWidget { final AppDatabase db; final ModuleKind kind; final dynamic item; const EntryDialog({super.key,required this.db,required this.kind,this.item}); @override State<EntryDialog> createState()=>_EntryDialogState(); }
class _EntryDialogState extends State<EntryDialog> {
  final form=GlobalKey<FormState>(); final c=<String,TextEditingController>{}; List<Customer> customers=[]; List<Site> sites=[];
  bool get editing=>widget.item!=null;
  @override void initState(){super.initState();_init();_relations();}
  void _init(){final x=widget.item;final m=<String,String>{};if(x!=null){switch(widget.kind){case ModuleKind.sites:m.addAll({'title':x.title,'address':x.address,'customerId':x.customerId??''});case ModuleKind.customers:m.addAll({'name':x.name,'contact':x.contact,'phone':x.phone,'address':x.address});case ModuleKind.orders:m.addAll({'title':x.title,'customerId':x.customerId??'','siteId':x.siteId?.toString()??'','status':x.status,'date':x.date,'price':x.price.toString()});case ModuleKind.employees:m.addAll({'name':x.name,'role':x.role,'targetHours':x.targetHours.toString()});case ModuleKind.time:m.addAll({'employeeName':x.employeeName,'siteId':x.siteId.toString(),'date':_fmtDate(x.date),'startTime':_fmtTime(x.startTime),'endTime':x.endTime==null?'':_fmtTime(x.endTime!),'breakMinutes':x.breakMinutes.toString(),'notes':x.notes??''});case ModuleKind.reports:m.addAll({'title':x.title,'siteId':x.siteId?.toString()??'','date':x.date,'content':x.content});case ModuleKind.materials:m.addAll({'name':x.name,'articleNumber':x.articleNumber??'','category':x.category??'','unit':x.unit,'stock':x.stock.toString(),'minimumStock':x.minimumStock.toString(),'location':x.location??'','unitPrice':x.unitPrice?.toString()??'','notes':x.notes??''});case ModuleKind.machines:m.addAll({'name':x.name,'serialNumber':x.serialNumber??'','operatingHours':x.operatingHours.toString(),'status':x.status,'notes':x.notes??''});case ModuleKind.tasks:m.addAll({'title':x.title,'description':x.description??'','siteId':x.siteId?.toString()??'','category':x.category,'priority':x.priority,'status':x.status,'dueDate':x.dueDate==null?'':_fmtDate(x.dueDate!)});}}for(final f in fields){c[f.key]=TextEditingController(text:m[f.key]??f.initial??'');}}
  Future<void> _relations()async{customers=await(widget.db.select(widget.db.customers)).get();sites=await(widget.db.select(widget.db.sites)).get();if(mounted)setState((){});}
