  Future<void> pickDate(String key)async{final d=await showDatePicker(context:context,firstDate:DateTime(2020),lastDate:DateTime(2035),initialDate:DateTime.tryParse(c[key]!.text)??DateTime.now());if(d!=null)c[key]!.text=_fmtDate(d);}
  Future<void> pickTime(String key)async{final p=c[key]!.text.split(':');final t=await showTimePicker(context:context,initialTime:TimeOfDay(hour:int.tryParse(p.first)??8,minute:p.length>1?int.tryParse(p[1])??0:0));if(t!=null)c[key]!.text='${t.hour.toString().padLeft(2,'0')}:${t.minute.toString().padLeft(2,'0')}';}
